-- Step 2 of 2: one-time initial data. Ledger-guarded: never recreates removed,
-- retired or edited plans. Requires the public pricing baseline to be frozen
-- first (runner) and records it as a rollback-able version BEFORE archiving.
BEGIN;
CREATE TABLE IF NOT EXISTS public.plan_seed_ledger (key text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
DO $seed$
DECLARE ids uuid[] := ARRAY[]::uuid[]; new_id uuid; premium uuid;
BEGIN
 IF EXISTS (SELECT 1 FROM public.plan_seed_ledger WHERE key='vynox-three-tier-2025') THEN RETURN; END IF;
 IF NOT EXISTS (SELECT 1 FROM qxlayer_commerce.pricing_publication WHERE singleton) THEN
  RAISE EXCEPTION 'Public pricing baseline is not frozen; run the plan-management runner, not this file directly.';
 END IF;
 IF EXISTS (SELECT 1 FROM public.tenant_subscriptions WHERE contract_snapshot IS NULL) THEN
  RAISE EXCEPTION 'Unfrozen subscription contracts remain; apply plan-management-profiles.sql first.';
 END IF;
 INSERT INTO qxlayer_commerce.pricing_publication_versions(revision,payload,reason,published_by)
  SELECT revision,payload,'Baseline captured before plan-management migration','migration:plan-management'
  FROM qxlayer_commerce.pricing_publication WHERE singleton
  AND NOT EXISTS (SELECT 1 FROM qxlayer_commerce.pricing_publication_versions v WHERE v.revision=pricing_publication.revision);
 UPDATE public.plans SET status='archived', updated_at=now(), revision=revision+1, updated_by='migration:plan-management' WHERE status <> 'archived';
